# 均線位置敘述：依 STOCK["tw_price"] 與 TECHNICAL 自動計算，避免每日手改遺漏而與實際價位矛盾
def _ma_comment():
    px = float(STOCK["tw_price"].replace(",", ""))
    mas = [("MA5", TECHNICAL["ma5"]), ("MA10", TECHNICAL["ma10"]),
           ("MA20", TECHNICAL["ma20"]), ("MA60", TECHNICAL["ma60"]),
           ("MA120", TECHNICAL["ma120"])]
    below = [f"{lbl}({v})" for lbl, v in mas if px < float(v.replace(",", ""))]
    above = [f"{lbl}({v})" for lbl, v in mas if px >= float(v.replace(",", ""))]
    parts = [f"現價 NT${STOCK['tw_price']}"]
    if below:
        parts.append("已跌破 " + "、".join(below))
    if above:
        parts.append("仍站上 " + "、".join(above) + "（當前長期支撐帶）")
    else:
        parts.append("四條均線全數失守")
    return "，".join(parts) + "。"

MA_COMMENT = _ma_comment()

